export interface PillarItem {
  id: string;
  number: string;
  title: string;
  subtitle: string;
  shortBudget?: string;
  budget: string;
  subsidyRate: string;
  heroImage: string;
  secondaryImage?: string;
  summary: string;
  highlights: string[];
  kpis: { label: string; value: string }[];
  legalFramework: string;
}

export interface CapexCategory {
  id: string;
  categoryTitle: string;
  subtotal: number;
  subtotalFormatted: string;
  items: {
    title: string;
    amount: number;
    amountFormatted: string;
    fundingSource: string;
    publicShare: string;
  }[];
}

export interface ScenarioMetrics {
  id: "conservative" | "baseline" | "optimistic";
  name: string;
  badge: string;
  description: string;
  milkTons: number;
  wineBottles: number;
  overnights: number;
  occupancyRate: string;
  trailVisitors: number;
  revenueYear5: number;
  revenueFormatted: string;
  jobsYear5: number;
  ebitdaRange: string;
  ebitdaMidpoint: number;
  communityDividend15Pct: string;
  taethaRoyalty25Pct: string;
}

export interface StakeholderBrief {
  id: string;
  group: "institutional" | "political" | "investors" | "community";
  name: string;
  role: string;
  phase: string;
  hookQuote: string;
  whatItIs: string;
  whyItMatters: string[];
  whatWeAsk: string[];
  metrics: { value: string; label: string }[];
  deliverable: string;
}

export interface HotspotPoint {
  id: string;
  title: string;
  category: string;
  x: number; // percentage on hero masterplan image
  y: number;
  capex: string;
  funding: string;
  image: string;
  description: string;
  metrics: string[];
}

